#!/usr/bin/env node
// generated by beerpowers v{{BEERPOWERS_VERSION}} — не править: обновляет /beerpowers:update
//
// Подпись сессии «© Клод Клодыч <отчество>» — отчество по модели, которая ведёт сессию. Ставится
// последней строкой всего, что сессия пишет от имени человека: задачи и комментарии в трекере
// (адаптер записи импортирует модуль), коммиты, описания MR, комментарии и ответы в ревью
// (.claude/reference/git-flow.md, «Подпись»).
//
//   node .claude/bin/lib/signature.mjs   # печатает подпись этой сессии; модель не узнать — exit 1
//
// Модель берётся из транскрипта сессии по CLAUDE_CODE_SESSION_ID: последний ответ модели
// называет её имя. Образец подписи из справки или прошлой задачи не копируется — сессия
// на Sonnet уже отправляла «Опусовича».

import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

// Отчество подписи — по семейству модели сессии.
export const PATRONYMIC = { opus: 'Опусович', sonnet: 'Сонетович', haiku: 'Хайкувич', fable: 'Фейблович' };
export const SIGN_PREFIX = '© Клод Клодыч';
// Подпись любой модели — для сверки текста, где подпись уже стоит.
export const SIGN_TEXT = `${SIGN_PREFIX} (?:${Object.values(PATRONYMIC).join('|')})`;
// Подсказка, когда модель не узнать.
export const SIGN_ANY = `${SIGN_PREFIX} <${Object.values(PATRONYMIC).join('|')} — по модели сессии>`;

export const configDir = process.env.CLAUDE_CONFIG_DIR || path.join(os.homedir(), '.claude');

// Семейство модели сессии по её транскрипту. Не узнать — null, и подпись остаётся на сессии.
export function sessionModel() {
  const id = process.env.CLAUDE_CODE_SESSION_ID || '';
  if (!/^[\w-]+$/.test(id)) return null;
  const root = path.join(configDir, 'projects');
  let dirs;
  try { dirs = fs.readdirSync(root); } catch { return null; }
  for (const dir of dirs) {
    const file = path.join(root, dir, `${id}.jsonl`);
    if (!fs.existsSync(file)) continue;
    const lines = fs.readFileSync(file, 'utf8').split('\n');
    for (let i = lines.length - 1; i >= 0; i--) {
      if (!lines[i].includes('"assistant"')) continue;
      let model;
      try { model = JSON.parse(lines[i]).message?.model; } catch { continue; }
      // Служебные записи без модели («<synthetic>») пропускаются.
      const family = Object.keys(PATRONYMIC).find((f) => String(model || '').includes(f));
      if (family) return family;
    }
  }
  return null;
}

// Подпись этой сессии или null.
export function ownSignature(family = sessionModel()) {
  return family ? `${SIGN_PREFIX} ${PATRONYMIC[family]}` : null;
}

const isMain = (() => {
  try {
    return Boolean(process.argv[1]) && fs.realpathSync(process.argv[1]) === fs.realpathSync(fileURLToPath(import.meta.url));
  } catch { return false; }
})();

if (isMain) {
  const sign = ownSignature();
  if (sign) {
    process.stdout.write(`${sign}\n`);
  } else {
    process.stderr.write(`модель сессии не узнать (нет транскрипта по CLAUDE_CODE_SESSION_ID) — подпись пиши руками по модели, которая ведёт сессию: ${SIGN_ANY}\n`);
    process.exit(1);
  }
}
